{"arguments": {"content": "#!/usr/bin/env python3
import sys
import openpyxl

def main():
    spreadsheet_path = sys.argv[1]
    output_path = sys.argv[2]

    wb = openpyxl.load_workbook(spreadsheet_path)
    ws = wb['Hárok1']

    # ---- Source table (columns C:I, rows 5-19) ----
    # Categories in row 5: C5:I5 -> HDD, SPD, FFI, ADW, HDW, LAD, TWC
    src_cats = {}
    for col_idx in range(3, 10):  # C..I (1-indexed cols 3..9)
        cat = ws.cell(row=5, column=col_idx).value
        src_cats[col_idx] = cat

    # Brand names in B6:B19, values in C:I for each row
    source = {}  # brand -> {category: value}
    for row in range(6, 20):
        brand = ws.cell(row=row, column=2).value
        if brand is None:
            continue
        source.setdefault(brand, {})
        for col_idx, cat in src_cats.items():
            v = ws.cell(row=row, column=col_idx).value
            if v is not None:
                source[brand][cat] = v

    # ---- Destination (columns K:S) ----
    # Categories in row 5: M5:S5 -> TWC, LAD, HDW, ADW, FFI, SPD, HDD
    dst_cats = {}
    for col_idx in range(13, 20):  # M..S (cols 13..19)
        cat = ws.cell(row=5, column=col_idx).value
        if cat is not None:
            dst_cats[col_idx] = cat

    # Fill M6:S11 by indexing source values
    # answer_position: M6:S11
    for row in range(6, 12):
        brand = ws.cell(row=row, column=12).value  # L column
        if brand is None:
            continue
        for col_idx, cat in dst_cats.items():
            val = source.get(brand, {}).get(cat)
            if val is not None:
                ws.cell(row=row, column=col_idx).value = val

    wb.save(output_path)
    print("Saved:", output_path)

if __name__ == '__main__':
    main()", "path": "/bench/answers/48983/solution.py"}, "name": "write"}
